"""生成绑定过去LiDAR独立审计的新开发审核页；只有用户提交才写人工记录。"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import shutil

from conceptgraph.completion.stage9 import OUTPUT, digest, dump


EVIDENCE_RUN = 'causal_dev_evidence_001'
HTML = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>过去LiDAR开发证据审核</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#183243;font:15px/1.6 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:20px}h1{font-size:26px;margin:0 0 10px}h2{font-size:19px;margin:8px 0}p{margin:8px 0}.card{background:white;border:1px solid #cedbe3;padding:15px;margin:14px 0;border-radius:7px;min-width:0}.notice{border-left:5px solid #b96d00}.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:16px}.grid .card{margin:0}canvas{width:100%;height:auto;border:1px solid #c5d2dc;background:white}select,button,input,textarea{font:inherit;padding:7px;max-width:100%}button{cursor:pointer}select{min-width:0}input[type=text],textarea{width:100%}textarea{min-height:100px;resize:vertical}label{display:block;margin:9px 0}.toggles label{display:inline-block;margin:7px 12px 7px 0}.muted{font-size:13px;color:#536a79;overflow-wrap:anywhere}.error{color:#a43119}.crops{display:flex;gap:9px;flex-wrap:wrap}.crops img{max-width:45%;max-height:160px;object-fit:contain;background:#eef1f3}.scroll{overflow-x:auto}table{border-collapse:collapse;font-size:13px;width:100%}th,td{padding:7px;text-align:left;border-bottom:1px solid #d8e2e9}td{overflow-wrap:anywhere}a{color:#075d92;overflow-wrap:anywhere}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}#source{overflow-wrap:anywhere}button:disabled{cursor:default;opacity:.5}@media(max-width:800px){main{padding:12px}.grid,.fields{grid-template-columns:1fr}h1{font-size:22px}.card{padding:12px}}</style>
<main><h1>过去LiDAR · 开发对象证据审核</h1>
<div class="card notice"><p>114个预设首、中、末帧。下方证据均来自真实RGB、CLIP裁剪、SAM和相机之前的LiDAR。<b>自动证据不等于人工结论。</b>颜色、细属性和身份无法确定时保持unknown或“证据不足”。</p><p>绿色官方框和实例只供审核与评价，未进入推理。官方sample GT仍较相机晚约33–42ms；首帧缺过去LiDAR时不得据此断言检测错误。此页不提供路线、正确锁定或实际到达证据。</p><p class="muted">RGB为JPEG显示副本；“实际CLIP裁剪”与模型原始输入逐像素核对。提交绑定本版本索引、证据文件、源预测和裁剪指纹，旧图身份审核不能直接转入新图。</p></div>
<div class="card"><button id="prev">上一帧</button> <select id="cases" aria-label="场景帧"></select> <button id="next">下一帧</button><p><label>查看方法 <select id="method"></select></label></p><div class="toggles"><label><input id="mask" type="checkbox" checked>选中SAM掩膜</label><label><input id="depth" type="checkbox" checked>稀疏LiDAR显示样本</label><label><input id="gt" type="checkbox" checked>官方评价框</label></div><p id="source" class="muted"></p><p id="metrics"></p></div>
<div class="grid"><div class="card"><h2>RGB、检测、实际掩膜与深度</h2><canvas id="rgb" width="1600" height="900"></canvas><p>黄：选中检测；青：其余检测；绿虚线：官方评价框；粉：有效深度显示样本。</p><label>待核验检测 <select id="detection"></select></label><div id="crops" class="crops"></div><p id="detection-info" class="muted"></p><h2>当前对象中心 · 世界XY（米）</h2><canvas id="bev" width="650" height="430"></canvas><p class="muted">绿：官方实例；蓝：当前方法预测节点；黑：相机位置。显示中心匹配，不代替真实身份审核。</p></div>
<div class="card"><h2>人工核验记录</h2><p id="human" class="muted">读取已有记录数量</p><label>真实审核者 <input id="reviewer" type="text" autocomplete="name" placeholder="填写审核者姓名或标识"></label><label>结论 <select id="label"><option>证据不足</option><option>正确关联</option><option>漏检</option><option>稀疏深度</option><option>投影偏差</option><option>错合并</option><option>重复节点</option><option>身份变化</option><option>语义错误</option><option>评测关联不足</option></select></label><div class="fields"><label>可见类别 <select id="category"><option>unknown</option><option>car</option><option>truck</option><option>bus</option><option>bicycle</option><option>motorcycle</option><option>pedestrian</option><option>traffic sign</option><option>traffic light</option><option>other</option></select></label><label>可见颜色 <select id="color"><option>unknown</option><option>red</option><option>blue</option><option>white</option><option>black</option><option>gray</option><option>silver</option><option>green</option><option>yellow</option><option>orange</option><option>brown</option><option>multiple</option></select></label></div><label>待审核图节点（多选；身份类结论必选） <select id="review-nodes" multiple size="4" aria-label="待审核图节点"></select></label><p class="muted">节点列表来自当前所选建图方法，不自动把检测分配给节点。身份变化需要额外跨帧证据；单帧看不清时选证据不足。</p><label>官方实例（无法确定留空）<input id="instance" type="text" list="instances" placeholder="仅填写当前帧可核验的实例token"><datalist id="instances"></datalist></label><label>细车型等属性 <input id="body-type" type="text" value="unknown"></label><label>审核依据 <textarea id="note" placeholder="说明依据来自哪个裁剪、深度、官方投影或三维对象；看不清时写明原因"></textarea></label><button id="submit">提交并保存本版本审核</button><p id="review-status" role="status"></p><p class="muted">提交只证明记录来源及结构已核验，标签正确性仍需独立复核。不自动产生第二审核者或一致性结论。</p></div></div>
<div class="card"><h2>当前预测节点与官方实例</h2><div class="scroll" id="nodes"></div><div class="scroll" id="truth"></div><p><a id="raw">本帧完整证据</a> · <a href="/annotation/causal_dev_evidence_001/audit_001/report.json">来源与像素独立核验</a> · <a href="/annotation/natural_command_review_001/index.html">原始自然指令审核</a></p></div><p id="error" class="error"></p></main>
<script>
const $=id=>document.getElementById(id);let manifest,current=null,position=0,selected=0,renderId=0;
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('文件未就绪：'+url);return r.json()}
const asset=name=>'/'+current.folder+name;
const loadImage=url=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('图片加载失败：'+url));image.src=url});
function table(headers,rows){const t=document.createElement('table'),h=t.insertRow();for(const text of headers){const c=document.createElement('th');c.textContent=text;h.append(c)}for(const row of rows){const tr=t.insertRow();for(const text of row)tr.insertCell().textContent=text}return t}
function resetForm(){for(const id of ['category','color'])$(id).value='unknown';$('label').value='证据不足';$('body-type').value='unknown';$('instance').value='';$('note').value='';for(const o of $('review-nodes').options)o.selected=false;$('review-status').textContent=''}
function fillOptions(node,rows){node.replaceChildren();for(const [value,text]of rows){const o=document.createElement('option');o.value=value;o.textContent=text;node.append(o)}}
function methodNodes(){fillOptions($('review-nodes'),current.predictions[$('method').value].map(n=>[n.node_id,`${n.node_id} · ${n.category}`]))}
function chooseDetection(){selected=+$('detection').value||0;resetForm();const d=current.detections[selected];$('crops').replaceChildren();$('submit').disabled=!d;if(d){for(const [key,label]of [['crop','检测框裁剪'],['actual_clip_crop','实际CLIP裁剪']])if(d[key]){const image=document.createElement('img');image.src=asset(d[key]);image.alt=label;image.title=label;$('crops').append(image)}$('detection-info').textContent=`检测${selected}；预测类别${d.category}；有效LiDAR ${d.valid_lidar_pixels}像素；深度分位数(m) ${JSON.stringify(d.depth_quantiles_m)}。预测类别不预填人工标签。`}else $('detection-info').textContent='本帧没有检测，不能提交不存在的检测索引。';return draw()}
async function show(){const ticket=++renderId,entry=manifest.cases[position];const data=await json('/'+entry.url);if(ticket!==renderId)return;current={...data,folder:entry.url.slice(0,entry.url.lastIndexOf('/')+1),entry};$('cases').value=String(position);$('source').textContent=`${current.scene} / 帧${current.frame_idx}；过去LiDAR证据版本 ${manifest.evidence_run}；源预测SHA ${current.source_frame_file_sha256}`;$('raw').href='/'+entry.url;const method=$('method').value;fillOptions($('method'),Object.keys(current.predictions).map(x=>[x,x]));$('method').value=method in current.predictions?method:'one_to_one_depth_quality';methodNodes();fillOptions($('detection'),current.detections.map((d,i)=>[String(i),`${i} · ${d.category} · 深度${d.valid_lidar_pixels}px`]));$('instances').replaceChildren();for(const g of current.official_evaluation_only){const o=document.createElement('option');o.value=g.instance_token;o.textContent=g.category;$('instances').append(o)}await chooseDetection()}
async function draw(){if(!current)return;const ticket=++renderId,ref=current,method=$('method').value,d=current.detections[selected];const image=await loadImage(asset(current.rgb));const mask=$('mask').checked&&d?await loadImage(asset(d.mask)):null;if(ticket!==renderId||ref!==current)return;const canvas=$('rgb');canvas.width=image.width;canvas.height=image.height;const c=canvas.getContext('2d');c.drawImage(image,0,0);if(mask){const temporary=document.createElement('canvas');temporary.width=image.width;temporary.height=image.height;const t=temporary.getContext('2d');t.drawImage(mask,0,0);const values=t.getImageData(0,0,image.width,image.height);for(let i=0;i<values.data.length;i+=4){const inside=values.data[i]>0;values.data[i]=255;values.data[i+1]=190;values.data[i+2]=0;values.data[i+3]=inside?75:0}t.putImageData(values,0,0);c.drawImage(temporary,0,0)}c.font='18px sans-serif';for(const p of current.detections){const b=p.bbox_xyxy;c.strokeStyle=p.detection_index===selected?'#ffb400':'#00b9de';c.lineWidth=p.detection_index===selected?4:2;c.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1]);c.fillStyle=c.strokeStyle;c.fillText(`${p.detection_index} ${p.category}`,b[0],Math.max(22,b[1]-4));if($('depth').checked){c.fillStyle='#ff2f81';for(const[u,v]of p.valid_depth_uvz)c.fillRect(u-2,v-2,4,4)}}if($('gt').checked){c.strokeStyle='#0a9d42';c.lineWidth=3;c.setLineDash([10,6]);for(const g of current.official_evaluation_only){const b=g.projected_bbox_xyxy;if(b)c.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1])}c.setLineDash([])}const m=current.metrics[method];$('metrics').textContent=`官方对象观测 ${m.truth}；中心匹配 ${m.true_positive}；预测 ${m.predictions}；中心误差 ${m.center_error_m_mean===null?'unknown':m.center_error_m_mean.toFixed(3)+'m'}。未知关联不能自动叫作误检。`;$('nodes').replaceChildren(table(['预测节点','类别','状态','速度m/s'],current.predictions[method].map(n=>[n.node_id,n.category,n.motion_state,n.velocity_mps.toFixed(2)])));$('truth').replaceChildren(table(['官方实例（评价）','类别','世界中心m'],current.official_evaluation_only.map(g=>[g.instance_token,g.category,g.center.map(x=>x.toFixed(2)).join(', ')])));drawMap(current.predictions[method]);canvas.dataset.rendered=current.scene+'_'+current.frame_idx+'_'+method}
function drawMap(nodes){const c=$('bev').getContext('2d');c.clearRect(0,0,650,430);const camera=[current.camera_pose[0][3],current.camera_pose[1][3]],points=[...nodes.map(n=>n.center),...current.official_evaluation_only.map(n=>n.center),camera],xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),x0=Math.min(...xs)-3,x1=Math.max(...xs)+3,y0=Math.min(...ys)-3,y1=Math.max(...ys)+3,scale=Math.min(600/(x1-x0),370/(y1-y0)),xy=p=>[325+(p[0]-(x0+x1)/2)*scale,215-(p[1]-(y0+y1)/2)*scale];c.font='12px sans-serif';for(const[rows,color,label]of [[current.official_evaluation_only,'#159747',n=>n.instance_token.slice(0,6)],[nodes,'#2365bb',n=>'n'+n.node_id]]){c.fillStyle=color;for(const n of rows){const[x,y]=xy(n.center);c.beginPath();c.arc(x,y,4,0,2*Math.PI);c.fill();c.fillText(label(n),x+5,y-5)}}const[x,y]=xy(camera);c.fillStyle='#182e3b';c.fillRect(x-4,y-4,8,8);c.fillText('相机',x+6,y+14);c.fillText(`等比例世界XY · 每像素 ${(1/scale).toFixed(3)}m`,12,418)}
async function humanStatus(){const value=await json('/api/review_status');$('human').textContent=`已有真实提交：开发 ${value.development_submissions}；自然指令 ${value.natural_submissions}。数量不等于可靠标签覆盖。`}
const safely=fn=>()=>Promise.resolve().then(fn).catch(error=>$('error').textContent=String(error));$('cases').onchange=safely(()=>{position=+$('cases').value;return show()});$('prev').onclick=safely(()=>{position=Math.max(0,position-1);return show()});$('next').onclick=safely(()=>{position=Math.min(manifest.cases.length-1,position+1);return show()});$('detection').onchange=safely(chooseDetection);$('method').onchange=safely(()=>{resetForm();methodNodes();return draw()});for(const id of ['gt','mask','depth'])$(id).onchange=safely(draw);
$('submit').onclick=async()=>{try{if(!current||!current.detections[selected])throw Error('请选择存在的检测');if(!$('reviewer').value.trim()||!$('note').value.trim())throw Error('请填写真实审核者和核验依据');const payload={evidence_run:manifest.evidence_run,evidence_index_sha256:manifest.evidence_index_sha256,evidence_file_sha256:current.entry.evidence_file_sha256,scene:current.scene,frame_idx:current.frame_idx,detection_index:selected,mapping_method:$('method').value,reviewed_node_ids:[...$('review-nodes').selectedOptions].map(o=>o.value),source_sha256:current.source_frame_file_sha256,reviewer:$('reviewer').value.trim(),label:$('label').value,observed_category:$('category').value,observed_color:$('color').value,instance_token:$('instance').value.trim(),body_type:$('body-type').value.trim(),note:$('note').value.trim(),submitted_at:new Date().toISOString()};$('submit').disabled=true;const response=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw Error(result.error);$('review-status').textContent='已保存本版本审核：'+result.submission_id+'。标签正确性仍需独立复核。';await humanStatus()}catch(error){$('review-status').textContent='未保存：'+error.message}finally{$('submit').disabled=!current?.detections[selected]}};
json('review_manifest.json').then(async value=>{manifest=value;fillOptions($('cases'),manifest.cases.map((r,i)=>[String(i),`${r.scene} / 帧${r.frame_idx}`]));await show();await humanStatus()}).catch(error=>$('error').textContent=String(error));
</script></html>'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run-id', required=True)
    args = parser.parse_args()
    bundle = OUTPUT/'annotation'/EVIDENCE_RUN
    index = json.loads((bundle/'index.json').read_text())
    audit = json.loads((bundle/'audit_001/report.json').read_text())
    files = json.loads((bundle/'audit_001/files.json').read_text())
    if (not audit['passed'] or audit['source_index_sha256'] != digest(bundle/'index.json')
            or audit['files_manifest_sha256'] != digest(bundle/'audit_001/files.json')):
        raise ValueError('开发审核需要当前独立证据审计')
    cases = []
    for case in index['cases']:
        path = (OUTPUT/case['url']).resolve()
        if not path.is_relative_to(bundle.resolve()) or files.get(str(path.relative_to(OUTPUT))) != digest(path):
            raise ValueError('开发证据版本或内容改变')
        cases.append(dict(case, evidence_file_sha256=digest(path)))
    destination = OUTPUT/'visualizations'/args.run_id
    destination.mkdir(parents=True, exist_ok=False)
    (destination/'index.html').write_text(HTML)
    dump(destination/'review_manifest.json', dict(evidence_run=EVIDENCE_RUN, cases=cases,
        evidence_index_sha256=digest(bundle/'index.json'), evidence_audit_sha256=digest(bundle/'audit_001/report.json'),
        automatic_evidence=True, human_records_created=0, actual_model_calls=0, goal_complete=False))
    shutil.copy2(__file__, destination/'generator_source.py')
    dump(destination/'manifest.json', dict(source_sha256=digest(Path(__file__)),
        index_html_sha256=digest(destination/'index.html'), review_manifest_sha256=digest(destination/'review_manifest.json'),
        case_count=len(cases), human_records_created=0, model_calls=0, goal_complete=False))
    print('http://localhost:8768/visualizations/'+args.run_id+'/index.html')


if __name__ == '__main__':
    main()
